window.MG_LAZY_DATA["data/lazy/resources/security-v26-052-b43ab6af05eb9f7a.json"]={sha256:"b43ab6af05eb9f7a1bf6a1314de82ce05b3f51a91f0917b5b65c16c4dc3d03c4",value:{"sources":[{"id":"v26-case-fc7498064b4397f3","url":"https://www.threatdragon.com/docs/","title":"OWASP Threat Dragon documentation","titleEn":"OWASP Threat Dragon documentation","publisher":"OWASP Threat Dragon","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-ea079221bd09f9cb","url":"https://cheatsheetseries.owasp.org/cheatsheets/Threat_Modeling_Cheat_Sheet.html","title":"OWASP Threat Modeling Cheat Sheet","titleEn":"OWASP Threat Modeling Cheat Sheet","publisher":"OWASP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-052","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-052","related":[{"id":"security-v26-053","referenceUrls":["https://asvs.owasp.org/"],"title":"OWASP ASVS：版本化需求與可重現驗收","titleEn":"OWASP ASVS: versioned requirements and repeatable acceptance","why":"用兩課的可觀察驗收條件比較模型邊界：交付資料流程圖、8條邊界契約、威脅到測試對照及新增流的變更審查。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a data-flow diagram, eight boundary contracts, threat-to-test mapping and a change review for added flows.","difference":"使用含版本的需求識別碼，分開測試通過、失敗、未知與不適用，避免將檢查表當認證。","differenceEn":"Use version-qualified requirement identifiers and separate pass, fail, unknown and non-applicable states without claiming certification.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["威脅模型是可修改的系統假設；緩解覆蓋=已有驗證的跨界流/所有跨界流，不能用威脅數推導攻擊機率。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 有8條跨界流；6條具有有效身分與加密測試，2條缺少備份存取測試。 已驗證跨界覆蓋=6/8=75%。","加權驗收分數=通過項權重總和/適用權重總和；權重是本課風險假設而非ASVS官方分數。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 選6個需求，權重3、3、2、2、1、1；前四項中第2項失敗，其餘5項通過。 總權重12，通過權重9，教學分數=9/12=75%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["A threat model records revisable system assumptions; mitigation coverage is tested crossings divided by all crossings, not an attack probability. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Eight flows cross trust boundaries; six have identity and transport tests, while two lack backup-access tests. Verified crossing coverage=6/8=75%.","Weighted acceptance equals passed weight divided by applicable weight; these weights are teaching assumptions, not official ASVS scores. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Select six requirements weighted 3,3,2,2,1,1; only the second requirement fails. Total weight is 12 and passed weight 9, giving a teaching score of 75%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-062","referenceUrls":["https://docs.sigstore.dev/cosign/verifying/verify/"],"title":"Sigstore Cosign：身分限制與簽章驗證","titleEn":"Sigstore Cosign: identity constraints in signature verification","why":"用兩課的可觀察驗收條件比較模型邊界：交付資料流程圖、8條邊界契約、威脅到測試對照及新增流的變更審查。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a data-flow diagram, eight boundary contracts, threat-to-test mapping and a change review for added flows.","difference":"把密碼學有效、預期身分、OIDC發行者與產物摘要分成獨立欄，為每種不符建立拒絕案例。","differenceEn":"Separate cryptographic validity, expected identity, OIDC issuer and artifact digest, with a rejection case for every mismatch.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["威脅模型是可修改的系統假設；緩解覆蓋=已有驗證的跨界流/所有跨界流，不能用威脅數推導攻擊機率。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 有8條跨界流；6條具有有效身分與加密測試，2條缺少備份存取測試。 已驗證跨界覆蓋=6/8=75%。","政策接受是交集；不能把「某人簽過」等同「預期發布流程簽過」。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 12個合成驗證包中10個密碼學有效；其中8個符合身分，7個也符合發行者與摘要。 通過率7/12=58.3333%，密碼學有效率10/12=83.3333%，兩者不同。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["A threat model records revisable system assumptions; mitigation coverage is tested crossings divided by all crossings, not an attack probability. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Eight flows cross trust boundaries; six have identity and transport tests, while two lack backup-access tests. Verified crossing coverage=6/8=75%.","Policy acceptance is an intersection; someone signed is not equivalent to the intended release workflow signed. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Of twelve synthetic bundles, ten are cryptographically valid; eight match identity and seven also match issuer and digest. Policy pass rate is 58.3333%, distinct from cryptographic validity of 83.3333%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-ded24302e1aeff08","url":"https://asvs.owasp.org/","title":"OWASP ASVS 5.0","titleEn":"OWASP ASVS 5.0","publisher":"OWASP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-597ad4586c0b891d","url":"https://docs.sigstore.dev/cosign/verifying/verify/","title":"Cosign signature verification","titleEn":"Cosign signature verification","publisher":"Sigstore","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
